   1 package security
   2 
   3 import (
   4     "errors"
   5     "fmt"
   6     "io/fs"
   7     "log"
   8     "os"
   9     "path/filepath"
  10     "strings"
  11     "time"
  12 
  13     "github.com/anthnel/devdesk/internal/git"
  14     "github.com/anthnel/devdesk/internal/patch"
  15     "github.com/anthnel/devdesk/internal/remediation"
  16     "github.com/anthnel/devdesk/internal/scan"
  17 )
  18 
  19 // The change a built-in fix would make (DEVDESK-753). One computation feeds the
  20 // preview and the confirmation of ctrl+o, so what is shown is what is written.
  21 
  22 // reasonPreviewStale is why a fix is refused on a file written after the scan:
  23 // the lines the scan reported may no longer be the lines of the file.
  24 const reasonPreviewStale = "The file changed after the scan — re-scan to preview the fix"
  25 
  26 // misconfigChange is the fix as it would land: the pure product shared by the
  27 // preview and ctrl+o.
  28 type misconfigChange struct {
  29     // File is the slash path, relative to the target, of the file the fix edits.
  30     File string
  31     // Lines is the formatted diff, sanitized, uncapped and uncut.
  32     Lines []string
  33     // Updated is the exact bytes ctrl+o writes.
  34     Updated []byte
  35     Scope   remediation.Scope
  36 }
  37 
  38 // misconfigChangeOf is the pure part of the computation: no I/O. It returns a
  39 // reason when the rule declines, and an error when the rewrite fails.
  40 func misconfigChangeOf(rule remediation.Rule, rel string, original []byte, f scan.Finding) (misconfigChange, string, error) {
  41     edits, reason := rule.Fix(original, f)
  42     if reason != "" {
  43         return misconfigChange{}, reason, nil
  44     }
  45     updated, err := patch.Rewrite(original, edits)
  46     if err != nil {
  47         return misconfigChange{}, "", fmt.Errorf("%s: %w", rel, err)
  48     }
  49     diff, err := patch.Diff(rel, original, edits)
  50     if err != nil {
  51         return misconfigChange{}, "", fmt.Errorf("%s: %w", rel, err)
  52     }
  53     return misconfigChange{
  54         File: rel, Lines: changeLines(diff), Updated: updated,
  55         Scope: rule.ScopeOf(updated, edits),
  56     }, "", nil
  57 }
  58 
  59 // changeLines formats a patch.Diff for display: the two header lines are
  60 // dropped (the file is named elsewhere), a hunk marker is indented by two spaces
  61 // so every line starts with +, - or a space, and each line is made safe for the
  62 // terminal. Nothing is capped or cut.
  63 //
  64 // Only the first two lines can be headers: a removed line "-- x" reads "--- x"
  65 // further down and is a change.
  66 func changeLines(diff string) []string {
  67     lines := strings.Split(diff, "\n")
  68     if lines[len(lines)-1] == "" {
  69         lines = lines[:len(lines)-1]
  70     }
  71     if len(lines) >= 2 && strings.HasPrefix(lines[0], "--- ") && strings.HasPrefix(lines[1], "+++ ") {
  72         lines = lines[2:]
  73     }
  74     if len(lines) == 0 {
  75         return nil
  76     }
  77     out := make([]string, len(lines))
  78     for i, l := range lines {
  79         if strings.HasPrefix(l, "@@") {
  80             l = "  " + l
  81         }
  82         out[i] = withoutControlSpace(l)
  83     }
  84     return out
  85 }
  86 
  87 // previewStale says whether a file written at modTime changed after the scan
  88 // that ended at scannedAt. A time that is not known cannot make a file stale.
  89 func previewStale(modTime, scannedAt time.Time) bool {
  90     return !modTime.IsZero() && !scannedAt.IsZero() && modTime.After(scannedAt)
  91 }
  92 
  93 // previewFailure words an error for the screen, never showing err.Error()
  94 // (Rule 128): the file is named, the detail is in the log.
  95 func previewFailure(rel string, err error) string {
  96     switch {
  97     case errors.Is(err, fs.ErrNotExist):
  98         return rel + " no longer exists"
  99     case errors.Is(err, fs.ErrPermission):
 100         return rel + " cannot be read"
 101     default:
 102         return "the fix could not be computed — check logs"
 103     }
 104 }
