 106 // resolveInside is the absolute path of file under target and its slash path
 107 // relative to target, or the reason it is refused: the path leaves the target
 108 // lexically, or a link on the way leads out of it. Nothing is read.
 109 func resolveInside(target, file string) (path, rel, reason string) {
 110     path, a := findingFilePath(scan.Finding{File: file}, target, true)
 111     if !a.Enabled() {
