 125 // the scan.
 126 func staleOn(path, rel string, scannedAt time.Time) error {
 127     info, err := os.Stat(path)
 128     if err != nil {
 129         return fmt.Errorf("%s: %w", rel, err)
 130     }
 131     if previewStale(info.ModTime(), scannedAt) {
 132         return errDeclined{reasonPreviewStale}
