 137 // computeMisconfigFix is the I/O side of the fix, shared by the Cmd ctrl+o starts
 138 // and by anything else that wants the same answer: the path is checked (lexically,
 139 // then through links), the files are measured against the end of the scan, and
 140 // only then is the edited file read. scannedAt is the end time of the result on
 141 // screen; the zero time never makes a file stale.
 142 func computeMisconfigFix(target string, f scan.Finding, scannedAt time.Time) MisconfigFixPreparedMsg {
 143     fail := func(err error) MisconfigFixPreparedMsg {
 144         return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: err}
 145     }
 146     decline := func(reason string) MisconfigFixPreparedMsg { return fail(errDeclined{reason}) }
 147 
 148     rule, ok := remediation.FixFor(f)
 149     if !ok {
 150         return decline(noFixReason(f))
 151     }
 152     // A rule that edits another file than the finding's reads the finding's own
 153     // to find it, so that one is checked before the rule is asked.
 154     findingPath := ""
 155     if rule.Target != nil {
 156         var reason string
 157         if findingPath, _, reason = resolveInside(target, f.File); reason != "" {
 158             return decline(reason)
 159         }
 160     }
 161     edited, reason := rule.FileFor(target, f)
 162     if reason != "" {
 163         return decline(reason)
 164     }
 165     path, rel, reason := resolveInside(target, edited)
 166     if reason != "" {
 167         return decline(reason)
 168     }
 169     if err := staleOn(path, rel, scannedAt); err != nil {
 170         return fail(err)
 171     }
 172     if findingPath != "" && findingPath != path {
 173         if err := staleOn(findingPath, f.File, scannedAt); err != nil {
 174             return fail(err)
 175         }
 176     }
 177     original, err := readFile(path)
 178     if err != nil {
 179         return fail(err)
 180     }
 181     change, reason, err := misconfigChangeOf(rule, rel, original, f)
 182     if err != nil {
 183         return fail(err)
 184     }
 185     if reason != "" {
 186         return decline(reason)
 187     }
 188     file := preparedWrite{File: rel, Path: path, Original: original, Updated: change.Updated}
 189     if file.State, err = git.StateOf(path); err != nil {
 190         log.Printf("ERROR [security/misconfig] git state of %s: %v", rel, err)
 191         file.StateErr = true
 192     }
 193     body := rule.Title + "\n\n"
 194     if rule.Warning != "" {
 195         body += "Warning: " + rule.Warning + "\n\n"
 196     }
 197     return MisconfigFixPreparedMsg{
 198         Target: target, File: file, FindingFile: f.File,
 199         Rule: f.ID, Instance: instanceOf(f), Body: body + strings.Join(change.Lines, "\n") + "\n",
 200         Scope: change.Scope, Lines: change.Lines,
 201     }
 202 }

