   8 // FileState is what git knows about one file: whether an edit to it can be
   9 // undone with git, and whether that undoing would also take the user's own
  10 // uncommitted work.
  11 type FileState int
  12 
  13 const (
  14     // FileOutsideRepo: the file is not in a git working copy. Nothing records
  15     // what it held before.
  16     FileOutsideRepo FileState = iota
  17     // FileUntracked: in a working copy, but git has never been told about it (or
  18     // ignores it). No history holds its previous content either.
  19     FileUntracked
  20     // FileModified: tracked, with changes not yet committed. `git checkout` would
  21     // undo an edit and the user's own changes together.
  22     FileModified
  23     // FileClean: tracked and identical to HEAD. Any edit can be seen with
  24     // `git diff` and undone with `git checkout`.
  25     FileClean
  26 )
  27 
  28 // StateOf reports what git knows about the file at path.
  29 //
  30 // A directory that is not a working copy is an answer (FileOutsideRepo), not an
  31 // error; anything else git refuses — a repository it will not open, git missing
  32 // — is returned, because it is not the same fact and reading it as "outside a
  33 // repository" would tell the user their file has no safety net when it might.
  34 func StateOf(path string) (FileState, error) {
  35     dir, name := filepath.Split(path)
  36     if dir == "" {
  37         dir = "."
  38     }
  39 
  40     if _, err := run(dir, "", "rev-parse", "--git-dir"); err != nil {
  41         if isNotARepository(err) {
  42             return FileOutsideRepo, nil
  43         }
  44         return FileOutsideRepo, err
  45     }
  46     if _, err := run(dir, "", "ls-files", "--error-unmatch", "--", name); err != nil {
  47         // A path git does not track is a failure of the command, by design.
  48         return FileUntracked, nil
  49     }
  50     out, err := run(dir, "", "status", "--porcelain", "--", name)
  51     if err != nil {
  52         return FileClean, err
  53     }
  54     if strings.TrimSpace(out) != "" {
  55         return FileModified, nil
  56     }
  57     return FileClean, nil
  58 }
  59 
  60 // isNotARepository reports whether err is git saying the directory is not in a
  61 // working copy. run keeps only git's last line, and a directory on another
  62 // filesystem than its parents gets two — "not a git repository (or any parent
  63 // up to mount point /)" and then "Stopping at filesystem boundary" — so both
  64 // spellings count. The text is English because nonInteractiveEnv forces
  65 // LC_ALL=C.
  66 func isNotARepository(err error) bool {
  67     msg := strings.ToLower(err.Error())
  68     return strings.Contains(msg, "not a git repository") ||
  69         strings.Contains(msg, "stopping at filesystem boundary")
  70 }
// WriteIfUnchanged replaces the file at path with updated, provided it still
// holds exactly expected — the content the change was computed from, and the one
// the user was shown and agreed to. Anything else is ErrChanged and the file is
// left alone: the user confirmed *that* diff, not another.
//
// The write goes through a temporary file in the same directory, then a rename,
// so a reader never sees half a file and a failure leaves the original in
// place. The file's permission bits are kept; a symbolic link is followed and
// its target replaced, not the link. The owner is not preserved when the process
// cannot chown, which is the ordinary case.
func WriteIfUnchanged(path string, expected, updated []byte) error {
	target, err := filepath.EvalSymlinks(path)
	if err != nil {
		return err
	}
	current, err := os.ReadFile(target)
	if err != nil {
		return err
	}
	if !bytes.Equal(current, expected) {
		return ErrChanged
	}
	info, err := os.Stat(target)
	if err != nil {
		return err
	}

	tmp, err := os.CreateTemp(filepath.Dir(target), filepath.Base(target)+".devdesk-*")
	if err != nil {
		return err
	}
	name := tmp.Name()
	fail := func(err error) error {
		_ = tmp.Close()
		_ = os.Remove(name)
		return err
	}
	if _, err := tmp.Write(updated); err != nil {
		return fail(fmt.Errorf("write %s: %w", name, err))
	}
	if err := tmp.Chmod(info.Mode().Perm()); err != nil {
		return fail(err)
	}
	if err := tmp.Close(); err != nil {
		_ = os.Remove(name)
		return err
	}
	if err := os.Rename(name, target); err != nil {
		_ = os.Remove(name)
		return err
	}
	return nil
}

